// Service worker: keeps a copy of the course so it works without internet.
// Generated by build/offline.mjs from build/sw.template.js — edit the template.
//
// Three caches:
//   shell  — the course's own pages, scripts and exercises. Network first, so
//            changes arrive whenever there's a connection; the saved copy is
//            used when there isn't. Renamed for every build.
//   vendor — R, the code editor and the fonts. These never change for a given
//            version, so the saved copy is used first.
//   rpkgs  — R packages (dplyr) fetched from webR's package site while online.
//
// The grader (/.netlify/functions/) is never cached: it can't work offline,
// and the course falls back to self-checking when it can't be reached.

const VERSION = "__VERSION__";
const SHELL = "rcourse-shell-" + VERSION;
const VENDOR = "rcourse-vendor-__VENDOR__";
const RPKGS = "rcourse-rpkgs-v1";
const KEEP = [SHELL, VENDOR, RPKGS];

self.addEventListener("install", () => self.skipWaiting());

self.addEventListener("activate", (e) => {
  e.waitUntil((async () => {
    for (const k of await caches.keys()) {
      if (k.startsWith("rcourse-") && !KEEP.includes(k)) await caches.delete(k);
    }
    await self.clients.claim();
  })());
});

const isRepo = (u) => u.hostname === "repo.r-wasm.org";

// R loads some library files lazily: it first asks for a file's size with a
// HEAD request, and may then ask for it in pieces with a Range header. Both
// have to be answered from the saved copy, or R stalls offline.

/** The saved copy of a file, whatever the method or range of the request. */
const savedCopy = (req) => caches.match(new Request(req.url), { ignoreSearch: false });

/** A HEAD answer: the saved copy's headers, no body. */
async function headFrom(res) {
  const headers = new Headers(res.headers);
  // Report the full size, and don't offer byte ranges — R then fetches the
  // file in one piece, which the saved copy can always answer.
  const size = (await res.clone().arrayBuffer()).byteLength;
  headers.set("Content-Length", String(size));
  headers.delete("Accept-Ranges");
  return new Response(null, { status: 200, headers });
}

/** A 206 answer for "bytes=a-b", cut from the saved copy. */
async function rangeFrom(res, range) {
  const buf = await res.arrayBuffer();
  const m = /^bytes=(\d*)-(\d*)$/.exec(range.trim());
  if (!m) return new Response(buf, { status: 200, headers: res.headers });
  let start = m[1] === "" ? buf.byteLength - Number(m[2]) : Number(m[1]);
  let end = m[1] === "" || m[2] === "" ? buf.byteLength - 1 : Number(m[2]);
  end = Math.min(end, buf.byteLength - 1);
  if (start > end || start < 0) {
    return new Response(null, { status: 416, headers: { "Content-Range": `bytes */${buf.byteLength}` } });
  }
  const headers = new Headers(res.headers);
  headers.set("Content-Range", `bytes ${start}-${end}/${buf.byteLength}`);
  headers.set("Content-Length", String(end - start + 1));
  return new Response(buf.slice(start, end + 1), { status: 206, headers });
}

async function cacheFirst(req, cacheName) {
  const hit = await savedCopy(req);
  if (hit) {
    if (req.method === "HEAD") return headFrom(hit);
    const range = req.headers.get("Range");
    return range ? rangeFrom(hit, range) : hit;
  }
  // Not saved yet: fetch the whole file once, keep it, then answer from it.
  const res = await fetch(new Request(req.url));
  if (!res.ok || res.status !== 200) return res;
  await (await caches.open(cacheName)).put(new Request(req.url), res.clone());
  if (req.method === "HEAD") return headFrom(res);
  const range = req.headers.get("Range");
  return range ? rangeFrom(res, range) : res;
}

async function networkFirst(req) {
  try {
    const res = await fetch(req);
    if (res.ok && res.status === 200) (await caches.open(SHELL)).put(req, res.clone());
    return res;
  } catch (err) {
    // Offline. A module page is the same file whatever ?ch= it was opened with.
    const hit = await caches.match(req) ?? await caches.match(req, { ignoreSearch: true });
    if (hit) return hit;
    // Not part of the course (online it would be "not found" too) — say so,
    // rather than failing as a network error.
    return new Response("Not available offline", { status: 404, headers: { "Content-Type": "text/plain" } });
  }
}

self.addEventListener("fetch", (e) => {
  const req = e.request;
  const url = new URL(req.url);
  if (url.pathname.startsWith("/.netlify/")) return;            // the grader: network only
  const vendorish = (url.origin === self.location.origin && url.pathname.includes("/vendor/")) || isRepo(url);
  // HEAD requests matter only for R's own files; everything else is GET.
  if (req.method !== "GET" && !(req.method === "HEAD" && vendorish)) return;
  if (url.origin === self.location.origin) {
    if (url.pathname.includes("/vendor/")) return e.respondWith(cacheFirst(req, VENDOR));
    return e.respondWith(networkFirst(req));
  }
  if (isRepo(url)) return e.respondWith(cacheFirst(req, RPKGS));
});
